e Muted}\" FontSize=\"11\" />\n      <Border Height=\"1\" Background=\"{DynamicResource BorderBrush}\" Margin=\"0,20\" />\n      <CheckBox Content=\"{Binding L[Images]}\" IsChecked=\"{Binding Images}\" FontWeight=\"SemiBold\" />\n      <TextBlock Text=\"{Binding L[ImageHint]}\" Style=\"{StaticResource Muted}\" FontSize=\"11\" Margin=\"0,8,0,10\" />\n      <Grid IsEnabled=\"{Binding Images}\"><Grid.ColumnDefinitions><ColumnDefinition /><ColumnDefinition Width=\"50\" /></Grid.ColumnDefinitions>\n       <Slider Minimum=\"50\" Maximum=\"100\" TickFrequency=\"1\" IsSnapToTickEnabled=\"True\" Value=\"{Binding ImageQuality}\" VerticalAlignment=\"Center\" />\n       <TextBlock Grid.Column=\"1\" Text=\"{Binding ImageQuality}\" HorizontalAlignment=\"Center\" />\n      </Grid>\n      <Border Height=\"1\" Background=\"{DynamicResource BorderBrush}\" Margin=\"0,20\" />\n      <CheckBox Content=\"{Binding L[HighBit]}\" IsChecked=\"{Binding AllowHighBitDepth}\" />\n      <TextBlock Text=\"{Binding L[HighBitHint]}\" Style=\"{StaticResource Muted}\" FontSize=\"11\" Margin=\"0,8,0,0\" />\n     </StackPanel>\n    </ScrollViewer>\n   </Border>\n   <TabControl Grid.Column=\"2\" BorderThickness=\"0\" Background=\"Transparent\" Foreground=\"{DynamicResource TextBrush}\">\n    <TabItem Header=\"{Binding L[Queue]}\">\n     <Grid Margin=\"0,16,0,0\"><Grid.RowDefinitions><RowDefinition Height=\"Auto\" /><RowDefinition Height=\"*\" /><RowDefinition Height=\"Auto\" /></Grid.RowDefinitions>\n      <DockPanel Margin=\"0,0,0,12\">\n       <StackPanel Orientation=\"Horizontal\" DockPanel.Dock=\"Right\">\n        <Button Content=\"{Binding L[SelectAll]}\" Click=\"SelectAll\" IsEnabled=\"{Binding Idle}\" Padding=\"10,6\" Margin=\"0,0,8,0\" />\n        <Button Content=\"{Binding L[Clear]}\" Click=\"Clear\" IsEnabled=\"{Binding Idle}\" Padding=\"10,6\" />\n       </StackPanel>\n       <TextBlock Text=\"{Binding L[QueueHint]}\" Style=\"{StaticResource Muted}\" VerticalAlignment=\"Center\" Margin=\"0,0,10,0\" />\n      </DockPanel>\n      <Border Grid.Row=\"1\" Background=\"{DynamicResource SurfaceBrush}\" CornerRadius=\"12\" BorderBrush=\"{DynamicResource BorderBrush}\" BorderThickness=\"1\" ClipToBounds=\"True\">\n       <DataGrid x:Name=\"QueueGrid\" ItemsSource=\"{Binding Files}\" IsReadOnly=\"False\" SelectionUnit=\"FullRow\" PreviewMouseDoubleClick=\"OpenSelected\">\n        <DataGrid.Columns>\n         <DataGridTemplateColumn Width=\"38\"><DataGridTemplateColumn.CellTemplate><DataTemplate>\n          <CheckBox IsChecked=\"{Binding Selected, UpdateSourceTrigger=PropertyChanged}\" HorizontalAlignment=\"Center\" VerticalAlignment=\"Center\" IsEnabled=\"{Binding DataContext.Idle, RelativeSource={RelativeSource AncestorType=Window}}\" />\n         </DataTemplate></DataGridTemplateColumn.CellTemplate></DataGridTemplateColumn>\n         <DataGridTemplateColumn Width=\"*\" MinWidth=\"190\"><DataGridTemplateColumn.HeaderTemplate><DataTemplate><TextBlock Text=\"{Binding DataContext.L[File], RelativeSource={RelativeSource AncestorType=Window}}\" /></DataTemplate></DataGridTemplateColumn.HeaderTemplate>\n          <DataGridTemplateColumn.CellTemplate><DataTemplate><StackPanel VerticalAlignment=\"Center\" ToolTip=\"{Binding Media.Path}\">\n           <TextBlock Text=\"{Binding Name}\" FontWeight=\"SemiBold\" TextTrimming=\"CharacterEllipsis\" />\n           <TextBlock Text=\"{Binding Kind}\" Foreground=\"{DynamicResource AccentBrush}\" FontSize=\"10\" />\n           <TextBlock Text=\"{Binding Folder}\" Foreground=\"{DynamicResource MutedBrush}\" FontSize=\"10\" TextTrimming=\"CharacterEllipsis\" FlowDirection=\"LeftToRight\" />\n          </StackPanel></DataTemplate></DataGridTemplateColumn.CellTemplate>\n         </DataGridTemplateColumn>\n         <DataGridTextColumn Binding=\"{Binding Tier}\" IsReadOnly=\"True\" Width=\"65\" Header=\"HD\" />\n         <DataGridTextColumn Binding=\"{Binding Size}\" IsReadOnly=\"True\" Width=\"95\" Header=\"MB / GB\" />\n         <DataGridTextColumn Binding=\"{Binding Duration}\" IsReadOnly=\"True\" Width=\"85\" Header=\"hh:mm:ss\" />\n         <DataGridTemplateColumn Width=\"140\"><DataGridTemplateColumn.HeaderTemplate><DataTemplate><TextBlock Text=\"{Binding DataContext.L[Status], RelativeSource={RelativeSource AncestorType=Window}}\" /></DataTemplate></DataGridTemplateColumn.HeaderTemplate>\n          <DataGridTemplateColumn.CellTemplate><DataTemplate><StackPanel VerticalAlignment=\"Center\" ToolTip=\"{Binding Detail}\">\n           <TextBlock Text=\"{Binding State}\" FontSize=\"11\" TextTrimming=\"CharacterEllipsis\" /><ProgressBar Value=\"{Binding Progress}\" Margin=\"0,8,0,0\" />\n          </StackPanel></DataTemplate></DataGridTemplateColumn.CellTemplate>\n         </DataGridTemplateColumn>\n        </DataGrid.Columns>\n       </DataGrid>\n      </Border>\n      <TextBlock Grid.Row=\"2\" Text=\"{Binding Estimate}\" Foreground=\"{DynamicResource AccentBrush}\" TextWrapping=\"Wrap\" Margin=\"0,12,0,0\" LineHeight=\"21\" />\n     </Grid>\n    </TabItem>\n    <TabItem Header=\"{Binding L[Profiles]}\">\n     <ScrollViewer VerticalScrollBarVisibility=\"Auto\" Margin=\"0,16,0,0\">\n      <StackPanel IsEnabled=\"{Binding Idle}\">\n       <TextBlock Text=\"{Binding L[ProfilesHint]}\" Style=\"{StaticResource Muted}\" Margin=\"0,0,0,16\" />\n       <ItemsControl ItemsSource=\"{Binding Profiles}\">\n        <ItemsControl.ItemsPanel><ItemsPanelTemplate><WrapPanel /></ItemsPanelTemplate></ItemsControl.ItemsPanel>\n        <ItemsControl.ItemTemplate><DataTemplate>\n         <Border Background=\"{DynamicResource SurfaceBrush}\" BorderBrush=\"{DynamicResource BorderBrush}\" BorderThickness=\"1\" CornerRadius=\"12\" Padding=\"16\" Margin=\"0,0,12,12\" Width=\"230\">\n          <StackPanel>\n           <CheckBox IsChecked=\"{Binding Enabled}\" Content=\"{Binding Tier}\" FontSize=\"19\" FontWeight=\"SemiBold\" Margin=\"0,0,0,14\" />\n           <TextBlock Text=\"{Binding DataContext.L[Quality], RelativeSource={RelativeSource AncestorType=Window}}\" Style=\"{StaticResource Muted}\" />\n           <Slider Minimum=\"16\" Maximum=\"30\" Value=\"{Binding Crf}\" IsSnapToTickEnabled=\"True\" TickFrequency=\"1\" Margin=\"0,8\" />\n           <TextBlock Text=\"{Binding Crf, StringFormat=CRF {0}}\" Foreground=\"{DynamicResource AccentBrush}\" FontWeight=\"SemiBold\" FlowDirection=\"LeftToRight\" />\n           <TextBlock Text=\"{Binding DataContext.L[Speed], RelativeSource={RelativeSource AncestorType=Window}}\" Style=\"{StaticResource Muted}\" Margin=\"0,12,0,6\" />\n           <ComboBox ItemsSource=\"{x:Static core:CompressionProfile.Presets}\" SelectedItem=\"{Binding Preset}\" FlowDirection=\"LeftToRight\" />\n           <TextBlock Text=\"{Binding DataContext.L[Codec], RelativeSource={RelativeSource AncestorType=Window}}\" Style=\"{StaticResource Muted}\" Margin=\"0,12,0,6\" />\n           <ComboBox ItemsSource=\"{x:Static core:CompressionProfile.Codecs}\" SelectedItem=\"{Binding Codec}\" FlowDirection=\"LeftToRight\" />\n           <TextBlock Text=\"{Binding SampleSummary}\" Foreground=\"{DynamicResource SuccessBrush}\" TextWrapping=\"Wrap\" FontSize=\"11\" Margin=\"0,10,0,0\" />\n          </StackPanel>\n         </Border>\n        </DataTemplate></ItemsControl.ItemTemplate>\n       </ItemsControl>\n       <Border Background=\"{DynamicResource AccentSoftBrush}\" CornerRadius=\"10\" Padding=\"16\" Margin=\"0,4,0,0\"><TextBlock Text=\"{Binding L[QualityGuide]}\" TextWrapping=\"Wrap\" LineHeight=\"22\" /></Border>\n      </StackPanel>\n     </ScrollViewer>\n    </TabItem>\n    <TabItem Header=\"{Binding L[Activity]}\">\n     <ListBox ItemsSource=\"{Binding Log}\" Margin=\"0,16,0,0\" Background=\"{DynamicResource SurfaceBrush}\" Foreground=\"{DynamicResource TextBrush}\" BorderThickness=\"0\" FontFamily=\"Consolas\" FontSize=\"12\" FlowDirection=\"LeftToRight\" ScrollViewer.HorizontalScrollBarVisibility=\"Auto\" />\n    </TabItem>\n    <TabItem Header=\"{Binding L[Guide]}\">\n     <ScrollViewer VerticalScrollBarVisibility=\"Auto\" Margin=\"0,16,0,0\">\n      <Border Background=\"{DynamicResource SurfaceBrush}\" CornerRadius=\"12\" Padding=\"24\"><StackPanel>\n       <TextBlock Text=\"{Binding L[GuideTitle]}\" FontSize=\"22\" FontWeight=\"SemiBold\" Margin=\"0,0,0,18\" />\n       <TextBlock Text=\"{Binding L[GuideText]}\" TextWrapping=\"Wrap\" LineHeight=\"25\" />\n       <TextBlock Text=\"{Binding L[Limits]}\" Style=\"{StaticResource Muted}\" Margin=\"0,20,0,0\" />\n      </StackPanel></Border>\n     </ScrollViewer>\n    </TabItem>\n   </TabControl>\n  </Grid>\n  <Border Grid.Row=\"3\" Background=\"{DynamicResource SurfaceBrush}\" BorderBrush=\"{DynamicResource BorderBrush}\" BorderThickness=\"1\" CornerRadius=\"12\" Padding=\"18\" Margin=\"0,18,0,0\">\n   <Grid><Grid.RowDefinitions><RowDefinition Height=\"Auto\" /><RowDefinition Height=\"Auto\" /></Grid.RowDefinitions>\n    <Grid><Grid.ColumnDefinitions><ColumnDefinition Width=\"*\" /><ColumnDefinition Width=\"Auto\" /></Grid.ColumnDefinitions>\n     <StackPanel VerticalAlignment=\"Center\" Margin=\"0,0,16,0\"><TextBlock Text=\"{Binding Status}\" FontWeight=\"SemiBold\" /><TextBlock Text=\"{Binding Current}\" Style=\"{StaticResource Muted}\" FontSize=\"11\" TextTrimming=\"CharacterEllipsis\" /></StackPanel>\n     <WrapPanel Grid.Column=\"1\">\n      <Button Content=\"{Binding L[Report]}\" Click=\"ExportReport\" Margin=\"0,0,8,0\" />\n      <Button Content=\"{Binding L[Sample]}\" Click=\"Sample\" IsEnabled=\"{Binding Idle}\" Margin=\"0,0,8,0\" />\n      <Button Content=\"{Binding L[Cancel]}\" Click=\"Cancel\" IsEnabled=\"{Binding Busy}\" Margin=\"0,0,8,0\" />\n      <Button Content=\"{Binding L[Start]}\" Click=\"Start\" IsEnabled=\"{Binding Idle}\" Style=\"{StaticResource PrimaryButton}\" />\n     </WrapPanel>\n    </Grid>\n    <ProgressBar Grid.Row=\"1\" Value=\"{Binding Overall}\" Margin=\"0,16,0,0\" />\n   </Grid>\n  </Border>\n </Grid>\n</Window>\n"
  },
