    "Path": "src/FramePress.App/MainViewModel.cs",
    "Text": "using System.Collections.ObjectModel;\nusing System.IO;\nusing System.Windows;\nusing FramePress.Core;\n\nnamespace FramePress.App;\npublic sealed class MainViewModel : Observable\n{\n    private CancellationTokenSource? _cancel;\n    private readonly MediaEngine _engine = new();\n    private bool _busy, _dark, _recursive, _images, _highBit;\n    private string _source = \"\", _destination = \"\", _status = \"\", _estimate = \"\", _current = \"\";\n    private int _mode, _imageQuality;\n    private double _overall;\n    private LanguageOption _language;\n    public Localizer L { get; }\n    public ObservableCollection<QueueItem> Files { get; } = [];\n    public ObservableCollection<CompressionProfile> Profiles { get; } = [];\n    public ObservableCollection<JobResult> Results { get; } = [];\n    public ObservableCollection<string> Log { get; } = [];\n    public LanguageOption[] Languages => Localizer.Languages;\n    public bool Busy { get => _busy; private set { Set(ref _busy, value); Raise(nameof(Idle)); } }\n    public bool Idle => !Busy;\n    public bool Dark { get => _dark; set => Set(ref _dark, value); }\n    public bool Recursive { get => _recursive; set => Set(ref _recursive, value); }\n    public bool Images { get => _images; set => Set(ref _images, value); }\n    public bool AllowHighBitDepth { get => _highBit; set => Set(ref _highBit, value); }\n    public int ImageQuality { get => _imageQuality; set => Set(ref _imageQuality, value); }\n    public int Mode { get => _mode; set => Set(ref _mode, value); }\n    public string Source { get => _source; set => Set(ref _source, value); }\n    public string Destination { get => _destination; set => Set(ref _destination, value); }\n    public string Status { get => _status; set => Set(ref _status, value); }\n    public string Estimate { get => _estimate; set => Set(ref _estimate, value); }\n    public string Current { get => _current; set => Set(ref _current, value); }\n    public double Overall { get => _overall; set => Set(ref _overall, value); }\n    public string CountText => Files.Count.ToString();\n    public string TotalSize => Display.Bytes(Files.Sum(f => (double)f.Media.Bytes));\n    public string SavedSize => Display.Bytes(Results.Where(r => r.State == \"Done\").Sum(r => (double)Math.Max(0, r.InputBytes - r.OutputBytes)));\n    public LanguageOption Language\n    {\n        get => _language;\n        set { if (Set(ref _language, value) && value is not null) { L.SetLanguage(value.Code); Raise(nameof(Direction)); } }\n    }\n    public FlowDirection Direction => L.Direction;\n    public MainViewModel()\n    {\n        var p = Preferences.Load(); L = new(p.Language);\n        _language = Languages.Single(l => l.Code == L.Code);\n        _dark = p.Dark; _recursive = p.Recursive; _images = p.Images; _imageQuality = p.ImageQuality; _highBit = p.AllowHighBitDepth;\n        foreach (var tier in CompressionProfile.Tiers) Profiles.Add(p.Profiles.FirstOrDefault(v => v.Tier == tier) ?? new() { Tier = tier });\n        Status = L[\"Ready\"];\n        Files.CollectionChanged += (_, _) => { Raise(nameof(CountText)); Raise(nameof(TotalSize)); };\n        Results.CollectionChanged += (_, _) => Raise(nameof(SavedSize));\n    }\n    public void Save()\n    {\n        try { new Preferences { Language = Language.Code, Dark = Dark, Recursive = Recursive, Images = Images, ImageQuality = ImageQuality, AllowHighBitDepth = AllowHighBitDepth, Profiles = Profiles.Select(p => p.Snapshot()).ToList() }.Save(); }\n        catch (Exception e) when (e is IOException or UnauthorizedAccessException) { AddLog(\"Settings: \" + e.Message); }\n    }\n    private void AddLog(string text)\n    {\n        if (!Application.Current.Dispatcher.CheckAccess()) { Application.Current.Dispatcher.Invoke(() => AddLog(text)); return; }\n        Log.Add(DateTime.Now.ToString(\"HH:mm:ss\") + \"  \" + text);\n        if (Log.Count > 500) Log.RemoveAt(0);\n    }\n    public void Cancel() { _cancel?.Cancel(); Status = L[\"Cancelling\"]; }\n    public void Clear()\n    {\n        if (Busy) return; Files.Clear(); Results.Clear(); Overall = 0; Estimate = \"\"; Current = \"\"; Status = L[\"Ready\"];\n    }\n    public async Task ScanAsync()\n    {\n        if (Busy || !Directory.Exists(Source)) { Status = L[\"ChooseFolderFirst\"]; return; }\n        var root = Path.GetFullPath(Source); var recursive = Recursive;\n        Clear(); Busy = true; _cancel = new(); Status = L[\"Scanning\"]; Save();\n        try\n        {\n            await _engine.VerifyToolsAsync(_cancel.Token);\n            var token = _cancel.Token;\n            var found = new Progress<MediaInfo>(m => Files.Add(new(m) { State = L[\"Ready\"] }));\n            await Task.Run(async () =>\n            {\n                foreach (var path in MediaEngine.Discover(root, recursive, AddLog))\n                {\n                    token.ThrowIfCancellationRequested();\n                    try { ((IProgress<MediaInfo>)found).Report(await _engine.ProbeAsync(path, token)); }\n                    catch (OperationCanceledException) { throw; }\n                    catch (Exception e) { AddLog(path + \": \" + e.Message); }\n                }\n            }, token);\n            Status = L[\"ScanComplete\"];\n            AddLog($\"Scan: {Files.Count} files; {Log.Count} log entries.\");\n            var transactions = Directory.EnumerateFiles(root, \".framepress-transaction-*.json\", new EnumerationOptions { RecurseSubdirectories = recursive, IgnoreInaccessible = true, AttributesToSkip = FileAttributes.ReparsePoint }).Any();\n            if (transactions) AddLog(L[\"RecoveryFound\"]);\n        }\n        catch (OperationCanceledException) { Status = L[\"Cancelled\"]; }\n        catch (Exception e) { Status = L[\"Error\"]; AddLog(e.Message); MessageBox.Show(e.Message, \"FramePress\"); }\n        finally { Busy = false; _cancel.Dispose(); _cancel = null; }\n    }\n    public async Task RunAsync(bool sample, QueueItem? selected)\n    {\n        if (Busy) return;\n        var jobs = Files.Where(f => f.Selected && !f.Completed && (f.Media.IsImage ? Images : Profiles.Single(p => p.Tier == f.Tier).Enabled)).ToList();\n        if (sample)\n        {\n            var candidate = selected is { Media.IsImage: false } ? selected : jobs.FirstOrDefault(f => !f.Media.IsImage);\n            jobs = candidate is null ? [] : [candidate];\n        }\n        if (jobs.Count == 0) { Status = L[\"NoFiles\"]; return; }\n        var snapshots = Profiles.ToDictionary(p => p.Tier, p => p.Snapshot());\n        try { foreach (var p in snapshots.Values) p.Validate(); }\n        catch (Exception e) { MessageBox.Show(e.Message, \"FramePress\"); return; }\n        if (ImageQuality is < 50 or > 100) { MessageBox.Show(\"Image quality: 50\u2013100\", \"FramePress\"); return; }\n        if (Mode == 1 && !sample && MessageBox.Show(L[\"ReplaceWarning\"], L[\"Confirm\"], MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;\n        var options = new JobOptions(Mode == 1, string.IsNullOrWhiteSpace(Destination) ? null : Destination, Source, ImageQuality, sample, AllowHighBitDepth);\n        Busy = true; _cancel = new(); Overall = 0; Estimate = \"\"; Save();\n        try\n        {\n            await _engine.VerifyToolsAsync(_cancel.Token);\n            var index = 0;\n            foreach (var item in jobs)\n            {\n                if (_cancel.IsCancellationRequested) break;\n                Current = item.Name; item.State = L[\"Encoding\"]; item.Detail = \"\";\n                var slot = index;\n                var updates = new Progress<JobProgress>(p =>\n                {\n                    item.Progress = p.Fraction * 100; item.State = L[p.Stage];\n                    Overall = (slot + p.Fraction) / jobs.Count * 100;\n                });\n                try\n                {\n                    var profile = item.Media.IsImage ? new CompressionProfile() : snapshots[item.Tier];\n                    var result = await Task.Run(() => _engine.ProcessAsync(item.Media, profile, options, updates, _cancel.Token));\n                    Results.Add(result); item.State = L[result.State]; item.Detail = result.Detail; item.Output = result.Output; item.Progress = 100;\n                    item.Completed = !sample && result.State is \"Done\" or \"LargerSkipped\";\n                    if (result.HourMinutes is { } minutes)\n                    {\n                        Estimate = string.Format(L[\"SampleEstimate\"], minutes.ToString(\"0.0\"), Display.Bytes(result.EstimatedFullBytes ?? 0));\n                        Profiles.Single(p => p.Tier == item.Tier).SampleSummary = Estimate;\n                    }\n                    AddLog(item.Name + \" \u00b7 \" + result.State + \" \u00b7 \" + result.Detail);\n                }\n                catch (OperationCanceledException) { item.State = L[\"Cancelled\"]; item.Progress = 0; break; }\n                catch (Exception e)\n                {\n                    item.State = L[\"Error\"]; item.Detail = e.Message;\n                    Results.Add(new(item.Media.Path, \"\", \"\", \"Error\", item.Media.Bytes, item.Media.Bytes, 0, e.Message)); AddLog(item.Name + \": \" + e.Message);\n                }\n                index++; Overall = index / (double)jobs.Count * 100;\n            }\n            Status = _cancel.IsCancellationRequested ? L[\"Cancelled\"] : L[\"Complete\"];\n        }\n        catch (OperationCanceledException) { Status = L[\"Cancelled\"]; }\n        catch (Exception e) { Status = L[\"Error\"]; AddLog(e.Message); MessageBox.Show(e.Message, \"FramePress\"); }\n        finally { Busy = false; _cancel.Dispose(); _cancel = null; }\n    }\n}\n"
  },
  {
    "Path": "src/FramePress.Core/Models.cs",
    "Text": "using System.ComponentModel;\nusing System.Globalization;\nusing System.Runtime.CompilerServices;\nusing System.Text.Json.Serialization;\n\nnamespace FramePress.Core;\n\npublic abstract class Observable : INotifyPropertyChanged\n{\n    public event PropertyChangedEventHandler? PropertyChanged;\n    protected void Raise([CallerMemberName] string? name = null) => PropertyChanged?.Invoke(this, new(name));\n    protected bool Set<T>(ref T field, T value, [CallerMemberName] string? name = null)\n    {\n        if (EqualityComparer<T>.Default.Equals(field, value)) return false;\n        field = value; Raise(name); return true;\n    }\n}\n\npublic sealed class CompressionProfile : Observable\n{\n    private bool _enabled = true;\n    private int _crf = 20;\n    private string _preset = \"medium\", _codec = \"H.264\", _sampleSummary = \"\";\n    public string Tier { get; set; } = \"1080p\";\n    public bool Enabled { get => _enabled; set => Set(ref _enabled, value); }\n    public int Crf { get => _crf; set { if (Set(ref _crf, value)) { Raise(nameof(QualityHint)); SampleSummary = \"\"; } } }\n    public string Preset { get => _preset; set { if (Set(ref _preset, value)) SampleSummary = \"\"; } }\n    public string Codec { get => _codec; set { if (Set(ref _codec, value)) SampleSummary = \"\"; } }\n    [JsonIgnore]\n    public string SampleSummary { get => _sampleSummary; set => Set(ref _sampleSummary, value); }\n    public string QualityHint => Crf <= 20 ? \"18\u201320 \u00b7 high / \u0645\u0631\u062a\u0641\u0639\u0629\" : Crf <= 23 ? \"21\u201323 \u00b7 balanced / \u0645\u062a\u0648\u0627\u0632\u0646\u0629\" : \"24\u201328 \u00b7 smaller / \u0623\u0635\u063a\u0631\";\n    public CompressionProfile Snapshot() => new() { Tier = Tier, Enabled = Enabled, Crf = Crf, Preset = Preset, Codec = Codec };\n    public void Validate()\n    {\n        if (Crf is < 16 or > 30) throw new ArgumentException(\"CRF must be between 16 and 30.\");\n        if (!Presets.Contains(Preset)) throw new ArgumentException(\"Unknown speed preset.\");\n        if (!Codecs.Contains(Codec)) throw new ArgumentException(\"Unknown video codec.\");\n    }\n    public static string[] Tiers { get; } = [\"SD\", \"720p\", \"1080p\", \"1440p\", \"4K\", \"8K+\"];\n    public static string[] Presets { get; } = [\"ultrafast\", \"veryfast\", \"fast\", \"medium\", \"slow\", \"slower\"];\n    public static string[] Codecs { get; } = [\"H.264\", \"H.265\"];\n}\n\npublic sealed record MediaInfo(string Path, bool IsImage, int Width, int Height, double Duration,\n    long Bytes, DateTime LastWriteUtc, string Tier, string PixelFormat, string Transfer,\n    string Primaries, string ColorSpace, int VideoStreams, int AudioStreams, bool HasSubtitles,\n    bool HasData, string Rotation)\n{\n    public bool IsHdr => Transfer is \"smpte2084\" or \"arib-std-b67\";\n    public bool IsHighBitDepth => PixelFormat.Contains(\"10\") || PixelFormat.Contains(\"12\") || PixelFormat.Contains(\"16\");\n    public string Dimensions => $\"{Width} \u00d7 {Height}\";\n    public string KindHint => IsImage ? \"Image\" : IsHdr ? \"HDR \u00b7 review\" : IsHighBitDepth ? \"10-bit+\" : \"SDR\";\n}\n\npublic sealed class QueueItem(MediaInfo media) : Observable\n{\n    private bool _selected = true;\n    private double _progress;\n    private string _state = \"Ready\", _detail = \"\", _output = \"\";\n    public MediaInfo Media { get; } = media;\n    public bool Selected { get => _selected; set => Set(ref _selected, value); }\n    public string Name => System.IO.Path.GetFileName(Media.Path);\n    public string Folder => System.IO.Path.GetDirectoryName(Media.Path) ?? \"\";\n    public string Tier => Media.Tier;\n    public string Dimensions => Media.Dimensions;\n    public string Size => Display.Bytes(Media.Bytes);\n    public string Duration => Media.IsImage ? \"\u2014\" : TimeSpan.FromSeconds(Media.Duration).ToString(@\"hh\\:mm\\:ss\");\n    public string Kind => Media.KindHint;\n    public double Progress { get => _progress; set => Set(ref _progress, value); }\n    public string State { get => _state; set => Set(ref _state, value); }\n    public string Detail { get => _detail; set => Set(ref _detail, value); }\n    public string Output { get => _output; set => Set(ref _output, value); }\n    public bool Completed { get; set; }\n}\n\npublic sealed record JobOptions(bool Replace, string? OutputRoot, string? SourceRoot,\n    int ImageQuality = 85, bool Sample = false, bool AllowHighBitDepth = false);\npublic sealed record JobProgress(double Fraction, string Stage, double EncodedSeconds);\npublic sealed record JobResult(string Source, string Output, string Backup, string State,\n    long InputBytes, long OutputBytes, double ElapsedSeconds, string Detail,\n    double? HourMinutes = null, double? EstimatedFullBytes = null);\npublic sealed record SampleEstimate(double HourMinutes, double FullBytes, double SampleSeconds);\n\npublic static class Display\n{\n    public static string Bytes(double value)\n    {\n        string[] units = [\"B\", \"KB\", \"MB\", \"GB\", \"TB\"];\n        var i = 0; while (value >= 1024 && i < units.Length - 1) { value /= 1024; i++; }\n        return value.ToString(\"0.##\", CultureInfo.InvariantCulture) + \" \" + units[i];\n    }\n}\n"
  },
  {
    "Path": ".github/workflows/windows.yml",
    "Text": "name: Build Windows installer\non:\n  workflow_dispatch:\n  push:\n    branches: [main]\n    tags: ['v*']\npermissions:\n  contents: read\njobs:\n  windows:\n    runs-on: windows-latest\n    steps:\n      - uses: actions/checkout@v5\n      - uses: actions/setup-dotnet@v5\n        with:\n          dotnet-version: '10.0.x'\n      - name: Install media tools and installer compiler\n        shell: pwsh\n        run: |\n          choco install ffmpeg nsis -y --no-progress\n          $ff = Get-ChildItem C:\\ProgramData\\chocolatey\\lib\\ffmpeg -Filter ffmpeg.exe -Recurse | Select-Object -First 1\n          if (!$ff) { throw 'FFmpeg binary not found' }\n          ./tools/Copy-FFmpeg.ps1 -BinDirectory $ff.DirectoryName\n      - name: Test, publish and create installer\n        shell: pwsh\n        run: ./Build-Release.ps1\n      - name: WPF startup and render smoke test\n        shell: pwsh\n        run: |\n          $process = Start-Process ./artifacts/publish/FramePress.App.exe -ArgumentList \"--smoke-test\" -PassThru\n          if (!$process.WaitForExit(60000)) { $process.Kill(); throw \"WPF smoke test timed out\" }\n          if ($process.ExitCode -ne 0) { throw \"WPF startup or binding validation failed\" }\n      - uses: actions/upload-artifact@v4\n        with:\n          name: FramePress-Windows\n          path: |\n            artifacts/FramePress-v0.2.0-Setup.exe\n            artifacts/publish/**\n            artifacts/FramePress-ui-*.png\n            artifacts/wpf-bindings.log\n          if-no-files-found: error\n"
  },
  {
    "Path": "docs/UI-LANGUAGE-FIX.md",
    "Text": "# Arabic and appearance repair\n\nThis repair addresses the reported Windows screenshot:\n\n- Arabic and other Unicode text are reinstalled from clean UTF-8 sources.\n- The repair script contains ASCII characters only and transports text as JSON Unicode escapes. It remains readable by Windows PowerShell 5.1 even when saved as UTF-8 without a BOM or a legacy ANSI encoding.\n- Window background/foreground/font are set explicitly on MainWindow, avoiding reliance on the implicit base Window style.\n- Language selector uses an explicit Name item template, avoiding record ToString in the selection box.\n- Tab content and scrollbars use themed templates. The Windows 11 title bar requests the matching DWM dark/light appearance.\n- Size summaries display their units left-to-right inside Arabic layout.\n- The Windows smoke test now checks Arabic text, language selector rendering, RTL/LTR and actual window background for Arabic/English in both themes, and produces four screenshots. Runtime execution is still pending on Windows.\n\nClose FramePress, run Fix-FramePress-UI.ps1 from the source project root, then rebuild/run. The script backs up affected source files in a dated .framepress-ui-backup-* directory before writing and attempts rollback on write failure. It does not change videos, FFmpeg tools or user preferences.\n\nLocal checks: WPF compilation and a repair round-trip against intentionally corrupted Arabic resources. These do not replace visual verification on Windows.\n"
  },
  {
    "Path": "src/FramePress.App/Assets/Languages/ar.json",
    "Text": "{\n  \"Tagline\": \"\u0641\u064a\u062f\u064a\u0648\u0647\u0627\u062a\u0643\u060c \u0628\u0645\u0633\u0627\u062d\u0629 \u0623\u0642\u0644.\",\n  \"Theme\": \"\u0627\u0644\u062a\u0628\u062f\u064a\u0644 \u0628\u064a\u0646 \u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0641\u0627\u062a\u062d \u0648\u0627\u0644\u062f\u0627\u0643\u0646\",\n  \"Queued\": \"\u0645\u0644\u0641\u0627\u062a \u0627\u0644\u0642\u0627\u0626\u0645\u0629\",\n  \"SourceSize\": \"\u062d\u062c\u0645 \u0627\u0644\u0645\u0635\u0627\u062f\u0631\",\n  \"Saved\": \"\u0641\u0631\u0642 \u0627\u0644\u062d\u062c\u0645 \u00b7 \u062f\u0648\u0646 \u0627\u062d\u062a\u0633\u0627\u0628 \u0646\u0633\u062e \u0627\u0644\u0627\u0633\u062a\u0631\u062c\u0627\u0639\",\n  \"Source\": \"01 \u00b7 \u0627\u0644\u0645\u0635\u062f\u0631\",\n  \"ChooseFolder\": \"\u0627\u062e\u062a\u064a\u0627\u0631 \u0645\u062c\u0644\u062f\",\n  \"Recursive\": \"\u062a\u0636\u0645\u064a\u0646 \u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u062c\u0644\u062f\u0627\u062a \u0627\u0644\u062f\u0627\u062e\u0644\u064a\u0629\",\n  \"Scan\": \"\u0641\u062d\u0635 \u0627\u0644\u0645\u0644\u0641\u0627\u062a\",\n  \"SaveMode\": \"02 \u00b7 \u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u062d\u0641\u0638\",\n  \"Copies\": \"\u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0628\u0627\u0644\u0623\u0635\u0644 \u0648\u0625\u0646\u0634\u0627\u0621 \u0646\u0633\u062e \u0645\u0636\u063a\u0648\u0637\u0629\",\n  \"Replace\": \"\u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u0645\u0639 \u0646\u0633\u062e \u0627\u0633\u062a\u0631\u062c\u0627\u0639\",\n  \"BackupHint\": \"\u064a\u062d\u062a\u0641\u0638 \u0627\u0644\u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u0628\u0627\u0644\u0645\u0635\u0627\u062f\u0631 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u0643\u0646\u0633\u062e \u0627\u0633\u062a\u0631\u062c\u0627\u0639. \u0627\u0641\u062d\u0635\u0647\u0627 \u0642\u0628\u0644 \u062d\u0630\u0641\u0647\u0627 \u064a\u062f\u0648\u064a\u064b\u0627.\",\n  \"Destination\": \"\u0627\u062e\u062a\u064a\u0627\u0631 \u0645\u062c\u0644\u062f \u0627\u0644\u0646\u062a\u0627\u0626\u062c\",\n  \"DestinationHint\": \"\u0641\u0627\u0631\u063a = \u0628\u062c\u0627\u0646\u0628 \u0643\u0644 \u0645\u0635\u062f\u0631. \u0627\u0644\u0646\u0633\u062e \u062a\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0644\u0645\u062c\u0644\u062f\u0627\u062a \u0627\u0644\u062f\u0627\u062e\u0644\u064a\u0629. \u0627\u0644\u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u064a\u0643\u0648\u0646 \u0641\u064a \u0645\u062c\u0644\u062f \u0627\u0644\u0645\u0635\u062f\u0631.\",\n  \"Images\": \"\u0636\u063a\u0637 \u0627\u0644\u0635\u0648\u0631 \u0623\u064a\u0636\u064b\u0627\",\n  \"ImageHint\": \"JPEG / PNG / WebP \u0625\u0644\u0649 WebP \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0627\u0644\u0623\u0628\u0639\u0627\u062f. RAW \u0648\u0627\u0644\u0635\u0648\u0631 \u0627\u0644\u0645\u062a\u062d\u0631\u0643\u0629 \u063a\u064a\u0631 \u0645\u062f\u0639\u0648\u0645\u0629.\",\n  \"HighBit\": \"\u0627\u0644\u0633\u0645\u0627\u062d \u0628\u0625\u062e\u0631\u0627\u062c SDR \u0628\u0639\u0645\u0642 10-bit\",\n  \"HighBitHint\": \"\u064a\u062a\u0637\u0644\u0628 H.265. \u064a\u062d\u0648\u0651\u0644 SDR \u0628\u0639\u0645\u0642 10-bit \u0623\u0648 \u0623\u0639\u0644\u0649 \u0625\u0644\u0649 10-bit 4:2:0. \u062a\u064f\u062a\u062e\u0637\u0649 \u0645\u0644\u0641\u0627\u062a HDR. \u0627\u062d\u062a\u0641\u0638 \u0628\u0645\u0635\u0627\u062f\u0631 \u0627\u0644\u0643\u0627\u0645\u064a\u0631\u0627.\",\n  \"Queue\": \"\u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0645\u0644\u0641\u0627\u062a\",\n  \"QueueHint\": \"\u0627\u0633\u062d\u0628 \u0645\u062c\u0644\u062f\u064b\u0627 \u0625\u0644\u0649 \u0627\u0644\u0646\u0627\u0641\u0630\u0629 \u00b7 \u0627\u0646\u0642\u0631 \u0645\u0631\u062a\u064a\u0646 \u0644\u062a\u062d\u062f\u064a\u062f \u0645\u0648\u0642\u0639 \u0627\u0644\u0645\u0644\u0641\",\n  \"SelectAll\": \"\u062a\u062d\u062f\u064a\u062f / \u0625\u0644\u063a\u0627\u0621 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0643\u0644\",\n  \"Clear\": \"\u0645\u0633\u062d \u0627\u0644\u0642\u0627\u0626\u0645\u0629\",\n  \"File\": \"\u0627\u0644\u0645\u0644\u0641\",\n  \"Status\": \"\u0627\u0644\u062d\u0627\u0644\u0629\",\n  \"Profiles\": \"\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u062f\u0642\u0627\u062a\",\n  \"ProfilesHint\": \"\u0644\u0643\u0644 \u062f\u0642\u0629 \u0625\u0639\u062f\u0627\u062f\u0627\u062a\u0647\u0627 \u0627\u0644\u0645\u0633\u062a\u0642\u0644\u0629. \u062a\u0628\u0642\u0649 \u0627\u0644\u0623\u0628\u0639\u0627\u062f \u0648\u062a\u0648\u0642\u064a\u062a \u0627\u0644\u0625\u0637\u0627\u0631\u0627\u062a\u060c \u0648\u064a\u0634\u0645\u0644 \u0627\u0644\u062a\u0635\u0646\u064a\u0641 \u0627\u0644\u0641\u064a\u062f\u064a\u0648 \u0627\u0644\u0623\u0641\u0642\u064a \u0648\u0627\u0644\u0639\u0645\u0648\u062f\u064a.\",\n  \"Quality\": \"\u0627\u0644\u062c\u0648\u062f\u0629 \u00b7 CRF\",\n  \"Speed\": \"\u0633\u0631\u0639\u0629 \u0627\u0644\u062a\u0631\u0645\u064a\u0632\",\n  \"Codec\": \"\u062a\u0631\u0645\u064a\u0632 \u0627\u0644\u0641\u064a\u062f\u064a\u0648\",\n  \"QualityGuide\": \"CRF 18\u201320: \u062c\u0648\u062f\u0629 \u0645\u0631\u062a\u0641\u0639\u0629 \u00b7 21\u201323: \u0645\u062a\u0648\u0627\u0632\u0646\u0629 \u00b7 24\u201328: \u062d\u062c\u0645 \u0623\u0635\u063a\u0631. \u0627\u0644\u0631\u0642\u0645 \u0627\u0644\u0623\u0642\u0644 \u064a\u0639\u0646\u064a \u062c\u0648\u062f\u0629 \u0623\u0639\u0644\u0649. \u0644\u0627 \u062a\u0648\u062c\u062f \u0646\u0633\u0628\u0629 \u062b\u0627\u0628\u062a\u0629 \u0644\u062e\u0633\u0627\u0631\u0629 \u0627\u0644\u062c\u0648\u062f\u0629. \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u0627\u0644\u0623\u0628\u0637\u0623 \u064a\u0633\u062a\u063a\u0631\u0642 \u0648\u0642\u062a\u064b\u0627 \u0623\u0637\u0648\u0644 \u0644\u062a\u062d\u0633\u064a\u0646 \u0643\u0641\u0627\u0621\u0629 \u0627\u0644\u0636\u063a\u0637.\",\n  \"Activity\": \"\u0633\u062c\u0644 \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a\",\n  \"Guide\": \"\u0627\u0644\u062f\u0644\u064a\u0644\",\n  \"GuideTitle\": \"\u0627\u0628\u062f\u0623 \u0628\u0639\u064a\u0646\u0629 \u0642\u0628\u0644 \u0627\u0644\u062f\u0641\u0639\u0629\",\n  \"GuideText\": \"1. \u0627\u062e\u062a\u0631 \u0627\u0644\u0645\u062c\u0644\u062f \u0648\u0627\u0641\u062d\u0635 \u0627\u0644\u0645\u0644\u0641\u0627\u062a.\\n2. \u062d\u062f\u062f \u0627\u0644\u062f\u0642\u0627\u062a \u0648\u0627\u0636\u0628\u0637 \u0627\u0644\u062c\u0648\u062f\u0629 \u0644\u0643\u0644 \u062f\u0642\u0629.\\n3. \u062c\u0631\u0651\u0628 \u0639\u064a\u0646\u0629 20 \u062b\u0627\u0646\u064a\u0629 \u0648\u0627\u0641\u062d\u0635\u0647\u0627 \u062f\u0627\u062e\u0644 \u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u0645\u0648\u0646\u062a\u0627\u062c.\\n4. \u0627\u0628\u062f\u0623 \u0627\u0644\u062f\u0641\u0639\u0629 \u062b\u0645 \u0631\u0627\u062c\u0639 \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0648\u0627\u0644\u0646\u062a\u0627\u0626\u062c.\\n\\nH.264 \u062f\u0627\u062e\u0644 MP4 \u0647\u0648 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a \u0644\u0644\u062a\u0648\u0627\u0641\u0642. H.265 \u0642\u062f \u064a\u0642\u0644\u0644 \u0627\u0644\u062d\u062c\u0645 \u0623\u0643\u062b\u0631 \u0644\u0643\u0646\u0647 \u0642\u062f \u064a\u0635\u0639\u0651\u0628 \u0627\u0644\u0645\u0648\u0646\u062a\u0627\u062c. \u0645\u0635\u0627\u062f\u0631 \u0627\u0644\u0643\u0627\u0645\u064a\u0631\u0627 \u062a\u0628\u0642\u0649 \u0646\u0633\u062e\u0629 \u0627\u0644\u0623\u0631\u0634\u064a\u0641. \u0627\u0644\u0646\u0627\u062a\u062c \u0627\u0644\u0645\u0636\u063a\u0648\u0637 \u0644\u064a\u0633 \u0635\u064a\u063a\u0629 \u0645\u0648\u0646\u062a\u0627\u062c \u062f\u0648\u0646 \u0641\u0642\u062f.\\n\\n\u0644\u0627 \u062d\u0633\u0627\u0628 \u0648\u0644\u0627 \u0631\u0641\u0639\u061b \u062a\u062a\u0645 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0645\u062d\u0644\u064a\u064b\u0627 \u0639\u0644\u0649 \u062c\u0647\u0627\u0632\u0643.\",\n  \"Limits\": \"\u062a\u0631\u0645\u064a\u0632 \u0628\u0627\u0644\u0645\u0639\u0627\u0644\u062c \u0641\u0642\u0637. \u0644\u0627 \u0625\u064a\u0642\u0627\u0641 \u0645\u0624\u0642\u062a \u0623\u0648 \u0627\u0633\u062a\u0626\u0646\u0627\u0641. \u062a\u064f\u062a\u062e\u0637\u0649 \u0645\u0644\u0641\u0627\u062a HDR. \u064a\u062a\u062d\u0648\u0644 \u0627\u0644\u0635\u0648\u062a \u0625\u0644\u0649 AAC. \u0628\u0639\u0636 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0643\u0627\u0645\u064a\u0631\u0627 \u0648\u0645\u0633\u0627\u0631\u0627\u062a \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0644\u0627 \u062a\u064f\u062d\u0641\u0638. \u062d\u0641\u0638 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0635\u0648\u0631 \u063a\u064a\u0631 \u0645\u0636\u0645\u0648\u0646. \u0627\u0644\u062a\u0634\u062e\u064a\u0635\u0627\u062a \u0627\u0644\u0641\u0646\u064a\u0629 \u0628\u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629. \u062a\u0642\u062f\u064a\u0631\u0627\u062a \u0627\u0644\u0648\u0642\u062a \u0648\u0627\u0644\u062d\u062c\u0645 \u062a\u0642\u0631\u064a\u0628\u064a\u0629.\",\n  \"Report\": \"\u062a\u0635\u062f\u064a\u0631 CSV\",\n  \"Sample\": \"\u0627\u062e\u062a\u0628\u0627\u0631 \u0639\u064a\u0646\u0629 20 \u062b\u0627\u0646\u064a\u0629\",\n  \"Cancel\": \"\u0625\u0644\u063a\u0627\u0621\",\n  \"Start\": \"\u0628\u062f\u0621 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629\",\n  \"Ready\": \"\u062c\u0627\u0647\u0632\",\n  \"Scanning\": \"\u062c\u0627\u0631\u064d \u0627\u0644\u0641\u062d\u0635\u2026\",\n  \"ScanComplete\": \"\u0627\u0643\u062a\u0645\u0644 \u0627\u0644\u0641\u062d\u0635\",\n  \"Cancelling\": \"\u062c\u0627\u0631\u064d \u0627\u0644\u0625\u0644\u063a\u0627\u0621\u2026\",\n  \"Cancelled\": \"\u0623\u064f\u0644\u063a\u064a\",\n  \"Error\": \"\u062e\u0637\u0623 \u00b7 \u0631\u0627\u062c\u0639 \u0627\u0644\u0633\u062c\u0644\",\n  \"NoFiles\": \"\u0644\u0627 \u062a\u0648\u062c\u062f \u0645\u0644\u0641\u0627\u062a \u0645\u0624\u0647\u0644\u0629 \u0645\u062d\u062f\u062f\u0629.\",\n  \"ChooseFolderFirst\": \"\u0627\u062e\u062a\u0631 \u0645\u062c\u0644\u062f \u0627\u0644\u0645\u0635\u062f\u0631 \u0623\u0648\u0644\u064b\u0627.\",\n  \"Confirm\": \"\u062a\u0623\u0643\u064a\u062f \u0627\u0644\u0627\u0633\u062a\u0628\u062f\u0627\u0644\",\n  \"ReplaceWarning\": \"\u0633\u062a\u064f\u0646\u0642\u0644 \u0627\u0644\u0645\u0635\u0627\u062f\u0631 \u0625\u0644\u0649 \u0646\u0633\u062e \u0627\u0633\u062a\u0631\u062c\u0627\u0639 \u0628\u0639\u062f \u0627\u0644\u062a\u062d\u0642\u0642. \u062a\u0638\u0644 \u0627\u0644\u0646\u0633\u062e \u062a\u0634\u063a\u0644 \u0645\u0633\u0627\u062d\u0629. \u0627\u062d\u062a\u0641\u0638 \u0628\u0647\u0627 \u062d\u062a\u0649 \u062a\u0641\u062d\u0635 \u0627\u0644\u0646\u062a\u0627\u0626\u062c \u062f\u0627\u062e\u0644 \u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u0645\u0648\u0646\u062a\u0627\u062c. \u0645\u062a\u0627\u0628\u0639\u0629\u061f\",\n  \"Encoding\": \"\u062c\u0627\u0631\u064d \u0627\u0644\u0636\u063a\u0637\",\n  \"Verifying\": \"\u062c\u0627\u0631\u064d \u0627\u0644\u062a\u062d\u0642\u0642\",\n  \"Done\": \"\u0627\u0643\u062a\u0645\u0644\",\n  \"LargerSkipped\": \"\u0627\u0644\u0646\u0627\u062a\u062c \u0623\u0643\u0628\u0631 \u00b7 \u062a\u064f\u062e\u0637\u064a\",\n  \"Complete\": \"\u0627\u0643\u062a\u0645\u0644\u062a \u0627\u0644\u0642\u0627\u0626\u0645\u0629\",\n  \"SampleEstimate\": \"\u062a\u0642\u062f\u064a\u0631 \u0641\u064a\u062f\u064a\u0648 \u0633\u0627\u0639\u0629: \u0646\u062d\u0648 {0} \u062f\u0642\u064a\u0642\u0629 \u00b7 \u062d\u062c\u0645 \u0627\u0644\u0646\u0627\u062a\u062c \u0627\u0644\u0643\u0627\u0645\u0644 \u0627\u0644\u0645\u062a\u0648\u0642\u0639: {1}. \u0645\u0646 \u0639\u064a\u0646\u0629 \u0648\u0627\u062d\u062f\u0629 \u0648\u0634\u0627\u0645\u0644 \u0627\u0644\u062a\u062d\u0642\u0642\u061b \u0627\u0644\u0646\u062a\u0627\u0626\u062c \u062a\u062e\u062a\u0644\u0641.\",\n  \"RecoveryFound\": \"\u062a\u0648\u062c\u062f \u0639\u0645\u0644\u064a\u0629 \u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u063a\u064a\u0631 \u0645\u0643\u062a\u0645\u0644\u0629. \u0627\u0641\u062d\u0635 \u0645\u0644\u0641\u0627\u062a .framepress-transaction-*.json \u0648\u0627\u0633\u062a\u0639\u062f \u0627\u0644\u0645\u0635\u062f\u0631 \u0645\u0646 \u0646\u0633\u062e\u0629 \u0627\u0644\u0627\u0633\u062a\u0631\u062c\u0627\u0639 \u0642\u0628\u0644 \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629 \u0645\u062c\u062f\u062f\u064b\u0627.\"\n}\n"
