    "Text": "{\n  \"Tagline\": \"Your footage. Less space.\",\n  \"Theme\": \"Switch light / dark theme\",\n  \"Queued\": \"Queued files\",\n  \"SourceSize\": \"Source size\",\n  \"Saved\": \"Smaller outputs \u00b7 backups excluded\",\n  \"Source\": \"01 \u00b7 SOURCE\",\n  \"ChooseFolder\": \"Choose folder\",\n  \"Recursive\": \"Include all subfolders\",\n  \"Scan\": \"Scan media\",\n  \"SaveMode\": \"02 \u00b7 SAVE MODE\",\n  \"Copies\": \"Keep originals + new copies\",\n  \"Replace\": \"Replace + recovery backups\",\n  \"BackupHint\": \"Replacement keeps the full originals as recovery backups. Review them before manually deleting.\",\n  \"Destination\": \"Choose output folder\",\n  \"DestinationHint\": \"Blank = next to each source. Copy mode keeps folder structure. Replacement uses the source folder.\",\n  \"Images\": \"Also compress images\",\n  \"ImageHint\": \"JPEG / PNG / WebP \u2192 WebP. Dimensions retained; RAW and animated images unsupported.\",\n  \"HighBit\": \"Allow 10-bit SDR output\",\n  \"HighBitHint\": \"H.265 only; 10-bit+ SDR converts to 10-bit 4:2:0. HDR is skipped. Keep camera masters.\",\n  \"Queue\": \"Queue\",\n  \"QueueHint\": \"Drop a folder here \u00b7 double-click a row to locate its file\",\n  \"SelectAll\": \"Select / deselect all\",\n  \"Clear\": \"Clear queue\",\n  \"File\": \"File\",\n  \"Status\": \"Status\",\n  \"Profiles\": \"Resolution profiles\",\n  \"ProfilesHint\": \"Each resolution has independent settings. Dimensions and frame timing are retained. Profiles classify both portrait and landscape footage.\",\n  \"Quality\": \"Quality \u00b7 CRF\",\n  \"Speed\": \"Encoding speed\",\n  \"Codec\": \"Video codec\",\n  \"QualityGuide\": \"CRF 18\u201320: high quality \u00b7 21\u201323: balanced \u00b7 24\u201328: smaller files. Lower means higher quality. Quality loss has no fixed percentage. Slow presets trade time for compression efficiency.\",\n  \"Activity\": \"Activity\",\n  \"Guide\": \"Guide\",\n  \"GuideTitle\": \"Start with a sample\",\n  \"GuideText\": \"1. Choose a folder and scan it.\\n2. Select resolution profiles and adjust quality.\\n3. Test a 20-second sample, then compare it in your editor.\\n4. Start the queue. Inspect the report and outputs.\\n\\nH.264 MP4 is the compatibility default. H.265 can be smaller but may be harder to edit. Camera originals remain your archive masters. The output is not a lossless editing intermediate.\\n\\nNo account or upload. All encoding takes place locally.\",\n  \"Limits\": \"CPU encoding. No pause/resume. HDR skipped. Audio becomes AAC. Data streams and some camera metadata may not survive. WebP image metadata preservation is not guaranteed. Technical diagnostics are English. Time and size are estimates, not promises.\",\n  \"Report\": \"Export CSV\",\n  \"Sample\": \"Test 20s sample\",\n  \"Cancel\": \"Cancel\",\n  \"Start\": \"Start queue\",\n  \"Ready\": \"Ready\",\n  \"Scanning\": \"Scanning\u2026\",\n  \"ScanComplete\": \"Scan complete\",\n  \"Cancelling\": \"Cancelling\u2026\",\n  \"Cancelled\": \"Cancelled\",\n  \"Error\": \"Error \u00b7 see activity\",\n  \"NoFiles\": \"No eligible files selected.\",\n  \"ChooseFolderFirst\": \"Choose a source folder first.\",\n  \"Confirm\": \"Confirm replacement\",\n  \"ReplaceWarning\": \"The original files will be moved to recovery backups after validation. Backups still consume space. Keep them until you have checked the output in your editor. Continue?\",\n  \"Encoding\": \"Encoding\",\n  \"Verifying\": \"Verifying output\",\n  \"Done\": \"Completed\",\n  \"LargerSkipped\": \"Larger \u00b7 skipped\",\n  \"Complete\": \"Queue finished\",\n  \"SampleEstimate\": \"One-hour estimate: \u2248 {0} min \u00b7 estimated full output: {1}. From one sample, including verification; results vary.\",\n  \"RecoveryFound\": \"Recovery transaction found. Inspect .framepress-transaction-*.json and restore the original backup before retrying.\"\n}\n"
  },
