    "Path": "src/FramePress.App/Assets/Languages/es.json",
    "Text": "{\n  \"Tagline\": \"Tus v\u00eddeos. Menos espacio.\",\n  \"Theme\": \"Tema claro / oscuro\",\n  \"Queued\": \"Archivos en cola\",\n  \"SourceSize\": \"Tama\u00f1o original\",\n  \"Saved\": \"Reducci\u00f3n sin copias de seguridad\",\n  \"Source\": \"01 \u00b7 ORIGEN\",\n  \"ChooseFolder\": \"Elegir carpeta\",\n  \"Recursive\": \"Incluir subcarpetas\",\n  \"Scan\": \"Analizar\",\n  \"SaveMode\": \"02 \u00b7 GUARDADO\",\n  \"Copies\": \"Originales y copias nuevas\",\n  \"Replace\": \"Reemplazar con copias de seguridad\",\n  \"BackupHint\": \"Los originales se conservan como copias de seguridad. Comprueba los resultados antes de borrarlas manualmente.\",\n  \"Destination\": \"Carpeta de salida\",\n  \"DestinationHint\": \"Vac\u00edo: junto al original. Las copias conservan las subcarpetas. El reemplazo usa la carpeta de origen.\",\n  \"Images\": \"Comprimir im\u00e1genes\",\n  \"ImageHint\": \"JPEG / PNG / WebP a WebP, manteniendo dimensiones. RAW e im\u00e1genes animadas no compatibles.\",\n  \"HighBit\": \"Permitir salida SDR de 10 bits\",\n  \"HighBitHint\": \"Solo H.265: SDR de 10 bits o m\u00e1s a 10 bits 4:2:0. Se omite HDR. Conserva los originales de c\u00e1mara.\",\n  \"Queue\": \"Cola\",\n  \"QueueHint\": \"Arrastra una carpeta \u00b7 doble clic para localizar el archivo\",\n  \"SelectAll\": \"Seleccionar / deseleccionar todo\",\n  \"Clear\": \"Vaciar cola\",\n  \"File\": \"Archivo\",\n  \"Status\": \"Estado\",\n  \"Profiles\": \"Perfiles de resoluci\u00f3n\",\n  \"ProfilesHint\": \"Ajustes por resoluci\u00f3n, tanto vertical como horizontal. Se conservan dimensiones y tiempos de fotogramas.\",\n  \"Quality\": \"Calidad \u00b7 CRF\",\n  \"Speed\": \"Velocidad\",\n  \"Codec\": \"C\u00f3dec de v\u00eddeo\",\n  \"QualityGuide\": \"CRF 18\u201320: alta calidad; 21\u201323: equilibrio; 24\u201328: menor tama\u00f1o. Un valor menor ofrece mayor calidad. No existe una p\u00e9rdida porcentual fija. Los modos lentos mejoran la eficiencia.\",\n  \"Activity\": \"Actividad\",\n  \"Guide\": \"Gu\u00eda\",\n  \"GuideTitle\": \"Empieza con una muestra\",\n  \"GuideText\": \"1. Elige y analiza una carpeta.\\n2. Ajusta cada resoluci\u00f3n.\\n3. Compara una muestra de 20 s en tu editor.\\n4. Inicia la cola y revisa el informe.\\n\\nH.264 MP4 prioriza compatibilidad. H.265 puede dificultar la edici\u00f3n. Conserva los originales de c\u00e1mara. Todo se procesa localmente, sin cuenta ni subida.\",\n  \"Limits\": \"Codificaci\u00f3n CPU, sin pausa ni reanudaci\u00f3n. HDR omitido, audio AAC. Pueden perderse metadatos. Diagn\u00f3sticos t\u00e9cnicos en ingl\u00e9s. Estimaciones aproximadas.\",\n  \"Report\": \"Exportar CSV\",\n  \"Sample\": \"Muestra de 20 s\",\n  \"Cancel\": \"Cancelar\",\n  \"Start\": \"Iniciar cola\",\n  \"Ready\": \"Listo\",\n  \"Scanning\": \"Analizando\u2026\",\n  \"ScanComplete\": \"An\u00e1lisis completo\",\n  \"Cancelling\": \"Cancelando\u2026\",\n  \"Cancelled\": \"Cancelado\",\n  \"Error\": \"Error \u00b7 ver actividad\",\n  \"NoFiles\": \"No hay archivos aptos seleccionados.\",\n  \"ChooseFolderFirst\": \"Elige una carpeta de origen.\",\n  \"Confirm\": \"Confirmar\",\n  \"ReplaceWarning\": \"Tras verificar, los originales se mover\u00e1n a copias de seguridad que siguen ocupando espacio. Revisa el resultado en tu editor antes de borrarlas. \u00bfContinuar?\",\n  \"Encoding\": \"Codificando\",\n  \"Verifying\": \"Verificando\",\n  \"Done\": \"Completado\",\n  \"LargerSkipped\": \"Mayor \u00b7 omitido\",\n  \"Complete\": \"Cola terminada\",\n  \"SampleEstimate\": \"Para una hora: \u2248 {0} min \u00b7 salida estimada: {1}. Una muestra con verificaci\u00f3n; resultados variables.\",\n  \"RecoveryFound\": \"Se encontr\u00f3 una transacci\u00f3n de recuperaci\u00f3n. Revisa .framepress-transaction-*.json y restaura la copia antes de reintentar.\"\n}\n"
  },
