    "Text": "{\n  \"Tagline\": \"\u0906\u092a\u0915\u0947 \u0935\u0940\u0921\u093f\u092f\u094b\u0964 \u0915\u092e \u091c\u0917\u0939\u0964\",\n  \"Theme\": \"\u0939\u0932\u094d\u0915\u0940 / \u0917\u0939\u0930\u0940 \u0925\u0940\u092e\",\n  \"Queued\": \"\u0915\u0924\u093e\u0930 \u092e\u0947\u0902 \u092b\u093c\u093e\u0907\u0932\u0947\u0902\",\n  \"SourceSize\": \"\u092e\u0942\u0932 \u0906\u0915\u093e\u0930\",\n  \"Saved\": \"\u092c\u0948\u0915\u0905\u092a \u0915\u0947 \u092c\u093f\u0928\u093e \u0915\u092e\u0940\",\n  \"Source\": \"01 \u00b7 \u0938\u094d\u0930\u094b\u0924\",\n  \"ChooseFolder\": \"\u092b\u093c\u094b\u0932\u094d\u0921\u0930 \u091a\u0941\u0928\u0947\u0902\",\n  \"Recursive\": \"\u0938\u092c\u092b\u093c\u094b\u0932\u094d\u0921\u0930 \u0936\u093e\u092e\u093f\u0932 \u0915\u0930\u0947\u0902\",\n  \"Scan\": \"\u0938\u094d\u0915\u0948\u0928 \u0915\u0930\u0947\u0902\",\n  \"SaveMode\": \"02 \u00b7 \u0938\u0939\u0947\u091c\u0928\u093e\",\n  \"Copies\": \"\u092e\u0942\u0932 \u0914\u0930 \u0928\u0908 \u092a\u094d\u0930\u0924\u093f\u092f\u093e\u0901\",\n  \"Replace\": \"\u092c\u0948\u0915\u0905\u092a \u0915\u0947 \u0938\u093e\u0925 \u092c\u0926\u0932\u0947\u0902\",\n  \"BackupHint\": \"\u092e\u0942\u0932 \u092b\u093c\u093e\u0907\u0932\u0947\u0902 \u092c\u0948\u0915\u0905\u092a \u092e\u0947\u0902 \u0930\u0939\u0924\u0940 \u0939\u0948\u0902\u0964 \u092e\u0948\u0928\u094d\u092f\u0941\u0905\u0932 \u0930\u0942\u092a \u0938\u0947 \u0939\u091f\u093e\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u092a\u0930\u093f\u0923\u093e\u092e \u091c\u093e\u0901\u091a\u0947\u0902\u0964\",\n  \"Destination\": \"\u0906\u0909\u091f\u092a\u0941\u091f \u092b\u093c\u094b\u0932\u094d\u0921\u0930\",\n  \"DestinationHint\": \"\u0916\u093e\u0932\u0940: \u0938\u094d\u0930\u094b\u0924 \u0915\u0947 \u092a\u093e\u0938\u0964 \u092a\u094d\u0930\u0924\u093f\u092f\u093e\u0901 \u0938\u092c\u092b\u093c\u094b\u0932\u094d\u0921\u0930 \u0930\u0916\u0924\u0940 \u0939\u0948\u0902\u0964 \u092c\u0926\u0932\u0928\u093e \u0938\u094d\u0930\u094b\u0924 \u092b\u093c\u094b\u0932\u094d\u0921\u0930 \u092e\u0947\u0902 \u0939\u094b\u0924\u093e \u0939\u0948\u0964\",\n  \"Images\": \"\u091a\u093f\u0924\u094d\u0930 \u0938\u0902\u092a\u0940\u0921\u093c\u0928\",\n  \"ImageHint\": \"JPEG / PNG / WebP \u0938\u0947 WebP, \u0906\u092f\u093e\u092e \u0938\u092e\u093e\u0928\u0964 RAW \u0914\u0930 \u090f\u0928\u093f\u092e\u0947\u091f\u0947\u0921 \u091a\u093f\u0924\u094d\u0930 \u0938\u092e\u0930\u094d\u0925\u093f\u0924 \u0928\u0939\u0940\u0902\u0964\",\n  \"HighBit\": \"10-\u092c\u093f\u091f SDR \u0906\u0909\u091f\u092a\u0941\u091f \u0915\u0940 \u0905\u0928\u0941\u092e\u0924\u093f\",\n  \"HighBitHint\": \"\u0915\u0947\u0935\u0932 H.265: 10-\u092c\u093f\u091f \u092f\u093e \u0905\u0927\u093f\u0915 SDR \u0915\u094b 10-\u092c\u093f\u091f 4:2:0 \u092c\u0928\u093e\u0924\u093e \u0939\u0948\u0964 HDR \u091b\u094b\u0921\u093c\u093e \u091c\u093e\u0924\u093e \u0939\u0948\u0964 \u0915\u0948\u092e\u0930\u093e \u092e\u0942\u0932 \u0930\u0916\u0947\u0902\u0964\",\n  \"Queue\": \"\u0915\u0924\u093e\u0930\",\n  \"QueueHint\": \"\u092b\u093c\u094b\u0932\u094d\u0921\u0930 \u0916\u0940\u0902\u091a\u0947\u0902 \u00b7 \u092b\u093c\u093e\u0907\u0932 \u0916\u094b\u091c\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0921\u092c\u0932-\u0915\u094d\u0932\u093f\u0915 \u0915\u0930\u0947\u0902\",\n  \"SelectAll\": \"\u0938\u092d\u0940 \u091a\u0941\u0928\u0947\u0902 / \u0939\u091f\u093e\u090f\u0901\",\n  \"Clear\": \"\u0915\u0924\u093e\u0930 \u0938\u093e\u092b\u093c \u0915\u0930\u0947\u0902\",\n  \"File\": \"\u092b\u093c\u093e\u0907\u0932\",\n  \"Status\": \"\u0938\u094d\u0925\u093f\u0924\u093f\",\n  \"Profiles\": \"\u0930\u093f\u091c\u093c\u0949\u0932\u094d\u092f\u0942\u0936\u0928 \u092a\u094d\u0930\u094b\u092b\u093c\u093e\u0907\u0932\",\n  \"ProfilesHint\": \"\u0939\u0930 \u0930\u093f\u091c\u093c\u0949\u0932\u094d\u092f\u0942\u0936\u0928 \u0915\u0940 \u0905\u0932\u0917 \u0938\u0947\u091f\u093f\u0902\u0917, \u0916\u0921\u093c\u0947 \u0914\u0930 \u091a\u094c\u0921\u093c\u0947 \u0935\u0940\u0921\u093f\u092f\u094b \u0915\u0947 \u0932\u093f\u090f\u0964 \u0906\u092f\u093e\u092e \u0914\u0930 \u092b\u093c\u094d\u0930\u0947\u092e \u0938\u092e\u092f \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924\u0964\",\n  \"Quality\": \"\u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u00b7 CRF\",\n  \"Speed\": \"\u0917\u0924\u093f\",\n  \"Codec\": \"\u0935\u0940\u0921\u093f\u092f\u094b \u0915\u094b\u0921\u0947\u0915\",\n  \"QualityGuide\": \"CRF 18\u201320: \u0909\u091a\u094d\u091a \u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e; 21\u201323: \u0938\u0902\u0924\u0941\u0932\u093f\u0924; 24\u201328: \u091b\u094b\u091f\u0940 \u092b\u093c\u093e\u0907\u0932\u0947\u0902\u0964 \u0915\u092e \u092e\u093e\u0928 \u0938\u0947 \u092c\u0947\u0939\u0924\u0930 \u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e\u0964 \u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u0939\u093e\u0928\u093f \u0915\u093e \u0924\u092f \u092a\u094d\u0930\u0924\u093f\u0936\u0924 \u0928\u0939\u0940\u0902\u0964 \u0927\u0940\u092e\u0947 \u092a\u094d\u0930\u0940\u0938\u0947\u091f \u0938\u0902\u092a\u0940\u0921\u093c\u0928 \u092c\u0947\u0939\u0924\u0930 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964\",\n  \"Activity\": \"\u0917\u0924\u093f\u0935\u093f\u0927\u093f\",\n  \"Guide\": \"\u0917\u093e\u0907\u0921\",\n  \"GuideTitle\": \"\u092a\u0939\u0932\u0947 \u0928\u092e\u0942\u0928\u093e \u091c\u093e\u0901\u091a\u0947\u0902\",\n  \"GuideText\": \"1. \u092b\u093c\u094b\u0932\u094d\u0921\u0930 \u091a\u0941\u0928\u0915\u0930 \u0938\u094d\u0915\u0948\u0928 \u0915\u0930\u0947\u0902\u0964\\n2. \u0939\u0930 \u0930\u093f\u091c\u093c\u0949\u0932\u094d\u092f\u0942\u0936\u0928 \u0915\u0940 \u0938\u0947\u091f\u093f\u0902\u0917 \u0915\u0930\u0947\u0902\u0964\\n3. 20 \u0938\u0947\u0915\u0902\u0921 \u0915\u093e \u0928\u092e\u0942\u0928\u093e \u0905\u092a\u0928\u0947 \u090f\u0921\u093f\u091f\u0930 \u092e\u0947\u0902 \u091c\u093e\u0901\u091a\u0947\u0902\u0964\\n4. \u0915\u0924\u093e\u0930 \u0936\u0941\u0930\u0942 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0930\u093f\u092a\u094b\u0930\u094d\u091f \u0926\u0947\u0916\u0947\u0902\u0964\\n\\n\u0905\u0928\u0941\u0915\u0942\u0932\u0924\u093e \u0915\u0947 \u0932\u093f\u090f H.264 MP4\u0964 H.265 \u0938\u0902\u092a\u093e\u0926\u0928 \u0915\u0920\u093f\u0928 \u0915\u0930 \u0938\u0915\u0924\u093e \u0939\u0948\u0964 \u092e\u0942\u0932 \u092b\u093c\u093e\u0907\u0932\u0947\u0902 \u0930\u0916\u0947\u0902\u0964 \u092c\u093f\u0928\u093e \u0916\u093e\u0924\u0947 \u092f\u093e \u0905\u092a\u0932\u094b\u0921 \u0915\u0947 \u0938\u094d\u0925\u093e\u0928\u0940\u092f \u092a\u094d\u0930\u094b\u0938\u0947\u0938\u093f\u0902\u0917\u0964\",\n  \"Limits\": \"CPU \u090f\u0928\u094d\u0915\u094b\u0921\u093f\u0902\u0917; \u0930\u094b\u0915\u0915\u0930 \u092b\u093f\u0930 \u0936\u0941\u0930\u0942 \u0915\u0930\u0928\u093e \u0928\u0939\u0940\u0902\u0964 HDR \u091b\u094b\u0921\u093c\u093e \u091c\u093e\u0924\u093e \u0939\u0948, \u0911\u0921\u093f\u092f\u094b AAC\u0964 \u0915\u0941\u091b \u092e\u0947\u091f\u093e\u0921\u0947\u091f\u093e \u0916\u094b \u0938\u0915\u0924\u093e \u0939\u0948\u0964 \u0924\u0915\u0928\u0940\u0915\u0940 \u0924\u094d\u0930\u0941\u091f\u093f\u092f\u093e\u0901 \u0905\u0902\u0917\u094d\u0930\u0947\u091c\u093c\u0940 \u092e\u0947\u0902\u0964 \u0905\u0928\u0941\u092e\u093e\u0928 \u0928\u093f\u0936\u094d\u091a\u093f\u0924 \u0928\u0939\u0940\u0902\u0964\",\n  \"Report\": \"CSV \u0928\u093f\u0930\u094d\u092f\u093e\u0924\",\n  \"Sample\": \"20 \u0938\u0947\u0915\u0902\u0921 \u0915\u093e \u0928\u092e\u0942\u0928\u093e\",\n  \"Cancel\": \"\u0930\u0926\u094d\u0926 \u0915\u0930\u0947\u0902\",\n  \"Start\": \"\u0936\u0941\u0930\u0942 \u0915\u0930\u0947\u0902\",\n  \"Ready\": \"\u0924\u0948\u092f\u093e\u0930\",\n  \"Scanning\": \"\u0938\u094d\u0915\u0948\u0928 \u091c\u093e\u0930\u0940\u2026\",\n  \"ScanComplete\": \"\u0938\u094d\u0915\u0948\u0928 \u092a\u0942\u0930\u094d\u0923\",\n  \"Cancelling\"