    "Path": "src/FramePress.App/Assets/Languages/it.json",
    "Text": "{\n  \"Tagline\": \"I tuoi video. Meno spazio.\",\n  \"Theme\": \"Tema chiaro / scuro\",\n  \"Queued\": \"File in coda\",\n  \"SourceSize\": \"Dimensione originale\",\n  \"Saved\": \"Riduzione senza backup\",\n  \"Source\": \"01 \u00b7 ORIGINE\",\n  \"ChooseFolder\": \"Scegli cartella\",\n  \"Recursive\": \"Includi sottocartelle\",\n  \"Scan\": \"Analizza\",\n  \"SaveMode\": \"02 \u00b7 SALVATAGGIO\",\n  \"Copies\": \"Originali e nuove copie\",\n  \"Replace\": \"Sostituisci con backup\",\n  \"BackupHint\": \"Gli originali restano nei backup. Controlla i risultati prima di eliminarli manualmente.\",\n  \"Destination\": \"Cartella di uscita\",\n  \"DestinationHint\": \"Vuoto: accanto alla sorgente. Le copie mantengono le sottocartelle. La sostituzione usa la cartella originale.\",\n  \"Images\": \"Comprimi immagini\",\n  \"ImageHint\": \"JPEG / PNG / WebP in WebP, dimensioni conservate. RAW e immagini animate non supportati.\",\n  \"HighBit\": \"Consenti uscita SDR a 10 bit\",\n  \"HighBitHint\": \"Solo H.265: SDR da almeno 10 bit a 10 bit 4:2:0. HDR ignorato. Conserva gli originali della videocamera.\",\n  \"Queue\": \"Coda\",\n  \"QueueHint\": \"Trascina una cartella \u00b7 doppio clic per individuare il file\",\n  \"SelectAll\": \"Seleziona / deseleziona tutto\",\n  \"Clear\": \"Svuota coda\",\n  \"File\": \"File\",\n  \"Status\": \"Stato\",\n  \"Profiles\": \"Profili di risoluzione\",\n  \"ProfilesHint\": \"Impostazioni per risoluzione, video verticali e orizzontali. Dimensioni e tempi dei fotogrammi conservati.\",\n  \"Quality\": \"Qualit\u00e0 \u00b7 CRF\",\n  \"Speed\": \"Velocit\u00e0\",\n  \"Codec\": \"Codec video\",\n  \"QualityGuide\": \"CRF 18\u201320: alta qualit\u00e0; 21\u201323: equilibrio; 24\u201328: file pi\u00f9 piccoli. Valori bassi migliorano la qualit\u00e0. Nessuna percentuale fissa di perdita. Le modalit\u00e0 lente possono migliorare la compressione.\",\n  \"Activity\": \"Attivit\u00e0\",\n  \"Guide\": \"Guida\",\n  \"GuideTitle\": \"Inizia con un campione\",\n  \"GuideText\": \"1. Scegli e analizza una cartella.\\n2. Regola ogni risoluzione.\\n3. Confronta un campione di 20 s nel programma di montaggio.\\n4. Avvia la coda e controlla il rapporto.\\n\\nH.264 MP4 per compatibilit\u00e0. H.265 pu\u00f2 complicare il montaggio. Conserva gli originali. Elaborazione locale, senza account o caricamenti.\",\n  \"Limits\": \"Codifica CPU, senza pausa o ripresa. HDR ignorato, audio AAC. Possibile perdita di metadati. Diagnostica tecnica in inglese. Stime indicative.\",\n  \"Report\": \"Esporta CSV\",\n  \"Sample\": \"Campione di 20 s\",\n  \"Cancel\": \"Annulla\",\n  \"Start\": \"Avvia coda\",\n  \"Ready\": \"Pronto\",\n  \"Scanning\": \"Analisi\u2026\",\n  \"ScanComplete\": \"Analisi completata\",\n  \"Cancelling\": \"Annullamento\u2026\",\n  \"Cancelled\": \"Annullato\",\n  \"Error\": \"Errore \u00b7 vedi attivit\u00e0\",\n  \"NoFiles\": \"Nessun file idoneo selezionato.\",\n  \"ChooseFolderFirst\": \"Scegli la cartella di origine.\",\n  \"Confirm\": \"Conferma\",\n  \"ReplaceWarning\": \"Dopo la verifica, gli originali saranno spostati in backup che occupano ancora spazio. Controlla nel programma di montaggio prima di eliminarli. Continuare?\",\n  \"Encoding\": \"Codifica\",\n  \"Verifying\": \"Verifica\",\n  \"Done\": \"Completato\",\n  \"LargerSkipped\": \"Pi\u00f9 grande \u00b7 ignorato\",\n  \"Complete\": \"Coda completata\",\n  \"SampleEstimate\": \"Per un\u2019ora: \u2248 {0} min \u00b7 uscita stimata: {1}. Da un campione, verifica inclusa; risultati variabili.\",\n  \"RecoveryFound\": \"Trovata una transazione di recupero. Controlla .framepress-transaction-*.json e ripristina il backup prima di riprovare.\"\n}\n"
