    "Path": "src/FramePress.App/Assets/Languages/zh.json",
    "Text": "{\n  \"Tagline\": \"\u89c6\u9891\u66f4\u5c0f\uff0c\u7a7a\u95f4\u66f4\u591a\u3002\",\n  \"Theme\": \"\u6d45\u8272 / \u6df1\u8272\u4e3b\u9898\",\n  \"Queued\": \"\u961f\u5217\u6587\u4ef6\",\n  \"SourceSize\": \"\u6e90\u6587\u4ef6\u5927\u5c0f\",\n  \"Saved\": \"\u7f29\u51cf\u91cf\uff08\u4e0d\u542b\u5907\u4efd\uff09\",\n  \"Source\": \"01 \u00b7 \u6765\u6e90\",\n  \"ChooseFolder\": \"\u9009\u62e9\u6587\u4ef6\u5939\",\n  \"Recursive\": \"\u5305\u542b\u6240\u6709\u5b50\u6587\u4ef6\u5939\",\n  \"Scan\": \"\u626b\u63cf\u5a92\u4f53\",\n  \"SaveMode\": \"02 \u00b7 \u4fdd\u5b58\u65b9\u5f0f\",\n  \"Copies\": \"\u4fdd\u7559\u539f\u4ef6\u4e0e\u65b0\u526f\u672c\",\n  \"Replace\": \"\u66ff\u6362\u5e76\u4fdd\u7559\u6062\u590d\u5907\u4efd\",\n  \"BackupHint\": \"\u539f\u6587\u4ef6\u4fdd\u7559\u4e3a\u6062\u590d\u5907\u4efd\u3002\u624b\u52a8\u5220\u9664\u5907\u4efd\u524d\u8bf7\u68c0\u67e5\u7ed3\u679c\u3002\",\n  \"Destination\": \"\u8f93\u51fa\u6587\u4ef6\u5939\",\n  \"DestinationHint\": \"\u7559\u7a7a\uff1a\u4fdd\u5b58\u5728\u6e90\u6587\u4ef6\u65c1\u3002\u526f\u672c\u4fdd\u7559\u5b50\u76ee\u5f55\u7ed3\u6784\u3002\u66ff\u6362\u4f7f\u7528\u6e90\u6587\u4ef6\u5939\u3002\",\n  \"Images\": \"\u540c\u65f6\u538b\u7f29\u56fe\u7247\",\n  \"ImageHint\": \"JPEG / PNG / WebP \u8f6c\u4e3a WebP\uff0c\u4fdd\u7559\u5c3a\u5bf8\u3002\u4e0d\u652f\u6301 RAW \u548c\u52a8\u753b\u56fe\u7247\u3002\",\n  \"HighBit\": \"\u5141\u8bb810\u4f4dSDR\u8f93\u51fa\",\n  \"HighBitHint\": \"\u4ec5\u9650 H.265\uff1a10\u4f4d\u53ca\u4ee5\u4e0a SDR \u8f6c\u4e3a10\u4f4d4:2:0\u3002\u8df3\u8fc7 HDR\u3002\u8bf7\u4fdd\u7559\u76f8\u673a\u539f\u4ef6\u3002\",\n  \"Queue\": \"\u961f\u5217\",\n  \"QueueHint\": \"\u62d6\u5165\u6587\u4ef6\u5939 \u00b7 \u53cc\u51fb\u884c\u53ef\u5b9a\u4f4d\u6587\u4ef6\",\n  \"SelectAll\": \"\u5168\u9009 / \u53d6\u6d88\u5168\u9009\",\n  \"Clear\": \"\u6e05\u7a7a\u961f\u5217\",\n  \"File\": \"\u6587\u4ef6\",\n  \"Status\": \"\u72b6\u6001\",\n  \"Profiles\": \"\u5206\u8fa8\u7387\u914d\u7f6e\",\n  \"ProfilesHint\": \"\u6bcf\u79cd\u5206\u8fa8\u7387\u72ec\u7acb\u8bbe\u7f6e\uff0c\u652f\u6301\u6a2a\u7ad6\u5c4f\u5206\u7c7b\u3002\u4fdd\u7559\u5c3a\u5bf8\u548c\u5e27\u65f6\u95f4\u3002\",\n  \"Quality\": \"\u8d28\u91cf \u00b7 CRF\",\n  \"Speed\": \"\u7f16\u7801\u901f\u5ea6\",\n  \"Codec\": \"\u89c6\u9891\u7f16\u7801\",\n  \"QualityGuide\": \"CRF 18\u201320\uff1a\u9ad8\u8d28\u91cf\uff1b21\u201323\uff1a\u5747\u8861\uff1b24\u201328\uff1a\u66f4\u5c0f\u6587\u4ef6\u3002\u6570\u503c\u8d8a\u4f4e\u8d28\u91cf\u8d8a\u9ad8\u3002\u753b\u8d28\u635f\u5931\u6ca1\u6709\u56fa\u5b9a\u767e\u5206\u6bd4\u3002\u6162\u901f\u9884\u8bbe\u53ef\u63d0\u9ad8\u538b\u7f29\u6548\u7387\u3002\",\n  \"Activity\": \"\u6d3b\u52a8\u8bb0\u5f55\",\n  \"Guide\": \"\u6307\u5357\",\n  \"GuideTitle\": \"\u5148\u6d4b\u8bd5\u6837\u672c\",\n  \"GuideText\": \"1. \u9009\u62e9\u5e76\u626b\u63cf\u6587\u4ef6\u5939\u3002\\n2. \u8bbe\u7f6e\u5404\u5206\u8fa8\u7387\u3002\\n3. \u5728\u526a\u8f91\u8f6f\u4ef6\u4e2d\u6bd4\u8f8320\u79d2\u6837\u672c\u3002\\n4. \u5f00\u59cb\u961f\u5217\u5e76\u68c0\u67e5\u62a5\u544a\u3002\\n\\n\u9ed8\u8ba4 H.264 MP4 \u6ce8\u91cd\u517c\u5bb9\u6027\u3002H.265 \u53ef\u80fd\u66f4\u96be\u526a\u8f91\u3002\u4fdd\u7559\u76f8\u673a\u539f\u4ef6\u3002\u5168\u90e8\u672c\u5730\u5904\u7406\uff0c\u65e0\u9700\u8d26\u6237\u6216\u4e0a\u4f20\u3002\",\n  \"Limits\": \"CPU \u7f16\u7801\uff0c\u65e0\u6682\u505c\u7eed\u4f20\u3002\u8df3\u8fc7 HDR\uff0c\u97f3\u9891\u8f6c AAC\u3002\u90e8\u5206\u5143\u6570\u636e\u53ef\u80fd\u4e22\u5931\u3002\u6280\u672f\u9519\u8bef\u4fe1\u606f\u4e3a\u82f1\u8bed\u3002\u65f6\u95f4\u4e0e\u5927\u5c0f\u5747\u4e3a\u4f30\u8ba1\u3002\",\n  \"Report\": \"\u5bfc\u51fa CSV\",\n  \"Sample\": \"\u6d4b\u8bd520\u79d2\u6837\u672c\",\n  \"Cancel\": \"\u53d6\u6d88\",\n  \"Start\": \"\u5f00\u59cb\u5904\u7406\",\n  \"Ready\": \"\u5c31\u7eea\",\n  \"Scanning\": \"\u626b\u63cf\u4e2d\u2026\",\n  \"ScanComplete\": \"\u626b\u63cf\u5b8c\u6210\",\n  \"Cancelling\": \"\u6b63\u5728\u53d6\u6d88\u2026\",\n  \"Cancelled\": \"\u5df2\u53d6\u6d88\",\n  \"Error\": \"\u9519\u8bef \u00b7 \u67e5\u770b\u8bb0\u5f55\",\n  \"NoFiles\": \"\u672a\u9009\u62e9\u7b26\u5408\u6761\u4ef6\u7684\u6587\u4ef6\u3002\",\n  \"ChooseFolderFirst\": \"\u8bf7\u5148\u9009\u62e9\u6e90\u6587\u4ef6\u5939\u3002\",\n  \"Confirm\": \"\u786e\u8ba4\",\n  \"ReplaceWarning\": \"\u9a8c\u8bc1\u540e\u539f\u4ef6\u5c06\u79fb\u81f3\u6062\u590d\u5907\u4efd\uff0c\u5907\u4efd\u4ecd\u5360\u7528\u7a7a\u95f4\u3002\u5728\u526a\u8f91\u8f6f\u4ef6\u4e2d\u68c0\u67e5\u540e\u518d\u5220\u9664\u3002\u7ee7\u7eed\uff1f\",\n  \"Encoding\": \"\u7f16\u7801\u4e2d\",\n  \"Verifying\": \"\u9a8c\u8bc1\u4e2d\",\n  \"Done\": \"\u5df2\u5b8c\u6210\",\n  \"LargerSkipped\": \"\u66f4\u5927 \u00b7 \u5df2\u8df3\u8fc7\",\n  \"Complete\": \"\u961f\u5217\u5b8c\u6210\",\n  \"SampleEstimate\": \"\u4e00\u5c0f\u65f6\u89c6\u9891\uff1a\u2248 {0} \u5206\u949f \u00b7 \u9884\u8ba1\u5b8c\u6574\u8f93\u51fa\uff1a{1}\u3002\u57fa\u4e8e\u4e00\u4e2a\u6837\u672c\uff0c\u542b\u9a8c\u8bc1\u65f6\u95f4\uff1b\u7ed3\u679c\u53ef\u80fd\u53d8\u5316\u3002\",\n  \"RecoveryFound\": \"\u53d1\u73b0\u6062\u590d\u4e8b\u52a1\u3002\u8bf7\u68c0\u67e5 .framepress-transaction-*.json \u5e76\u5728\u91cd\u8bd5\u524d\u6062\u590d\u5907\u4efd\u3002\"\n}\n"
  }
]
'@
$files = @($payload | ConvertFrom-Json)
$utf8 = New-Object System.Text.UTF8Encoding($false)
$backup = Join-Path $root ('.framepress-ui-backup-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [Guid]::NewGuid().ToString('N').Substring(0,8))
New-Item -ItemType Directory -Path $backup | Out-Null
$existed = @{}
foreach ($entry in $files) {
    $target = Join-Path $root $entry.Path
    $existed[$entry.Path] = Test-Path $target -PathType Leaf
    if ($existed[$entry.Path]) {
        $copy = Join-Path $backup $entry.Path
        New-Item -ItemType Directory -Path (Split-Path $copy -Parent) -Force | Out-Null
        Copy-Item -LiteralPath $target -Destination $copy -Force
    }
}
try {
    foreach ($entry in $files) {
        $target = Join-Path $root $entry.Path
        New-Item -ItemType Directory -Path (Split-Path $target -Parent) -Force | Out-Null
        [IO.File]::WriteAllText($target, [string]$entry.Text, $utf8)
    }
    $arFile = Join-Path $root 'src/FramePress.App/Assets/Languages/ar.json'
    $arabic = [IO.File]::ReadAllText($arFile, [Text.Encoding]::UTF8) | ConvertFrom-Json
    $expected = '"\u0628\u062f\u0621 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629"' | ConvertFrom-Json
    if ($arabic.Start -cne $expected) { throw 'Arabic UTF-8 verification failed.' }
} catch {
    $failure = $_
    foreach ($entry in $files) {
        $target = Join-Path $root $entry.Path
        try {
            if ($existed[$entry.Path]) { Copy-Item -LiteralPath (Join-Path $backup $entry.Path) -Destination $target -Force }
            elseif (Test-Path $target -PathType Leaf) { Remove-Item -LiteralPath $target -Force }
        } catch { Write-Warning "Automatic restore failed for $($entry.Path). Restore its copy from $backup" }
    }
    throw $failure
}
Write-Host 'Arabic resources, language selector and dark/light themes repaired.' -ForegroundColor Green
Write-Host "Source backups: $backup"
Write-Host 'Next: dotnet run --project ./src/FramePress.App/FramePress.App.csproj -c Release'
Write-Host 'On Windows, verify Arabic/English and both appearance modes.'
